import {
    Table,
    TableNameColumn,
    ConditionsColumn,
    ReferenceColumn,
    StringColumn,
    DomainPathColumn,
    DomainIdColumn,
    GenericColumn,
    IntegerColumn,
} from '@servicenow/sdk/core'

export const sys_ui_related_list = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        no_audit_delete: true,
        no_table_trace: true,
        update_synch_custom: true,
    },
    display: 'calculated_name',
    extends: 'sys_metadata',
    label: 'Related List',
    name: 'sys_ui_related_list',
    schema: {
        name: TableNameColumn({
            label: 'Table',
            tableReference: true,
        }),
        filter: ConditionsColumn({
            label: 'Filter',
            maxLength: 3500,
        }),
        view: ReferenceColumn({
            cascadeRule: 'delete',
            label: 'View',
            referenceTable: 'sys_ui_view',
        }),
        order_by: StringColumn({
            label: [
                {
                    hint: 'Default order by field for related list',
                    label: 'Order by',
                    plural: 'Order by',
                    language: 'en',
                },
            ],
        }),
        view_name: StringColumn({
            label: 'View name',
        }),
        calculated_name: StringColumn({
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: `(function calculatedFieldValue(current) {

	var viewName = !current.view.nil() ? current.view.title : '';
	var tableName = !current.name.nil() ? current.name.toString() : '';
	var tableLabel = tableName;
	if(tableName) {
		var gr = new GlideRecord(tableName);
		tableLabel = gr.isValid() ? gr.getLabel() : tableLabel;
	}
	return tableLabel + ' - ' + viewName; 

})(current);`,
            },
            label: 'Name',
            maxLength: 255,
        }),
        related_list: StringColumn({
            label: 'Related list',
            maxLength: 80,
        }),
        sys_user: ReferenceColumn({
            cascadeRule: 'delete',
            label: 'User',
            referenceTable: 'sys_user',
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the script belongs',
                    label: 'Domain',
                    plural: 'Domains',
                    language: 'en',
                },
            ],
        }),
        sys_id: GenericColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
        position: IntegerColumn({
            label: 'Position',
        }),
    },
    textIndex: true,
})
